package io.github.diodeme.ji.session.model;

import java.time.Instant;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/** Canonical Session aggregate with independently versioned child lifecycles. */
public record CanonicalSessionState(
        SessionId sessionId,
        SessionStatus status,
        Optional<SessionOutcome> outcome,
        long revision,
        Optional<Run> activeRun,
        List<Run> completedRuns,
        List<Compaction> compactions) {

    public CanonicalSessionState {
        Objects.requireNonNull(sessionId, "sessionId");
        Objects.requireNonNull(status, "status");
        Objects.requireNonNull(outcome, "outcome");
        requireTerminal(status == SessionStatus.TOMBSTONED, outcome, "session");
        requireRevision(revision);
        Objects.requireNonNull(activeRun, "activeRun");
        completedRuns = List.copyOf(completedRuns);
        compactions = List.copyOf(compactions);
        if (status != SessionStatus.AVAILABLE && activeRun.isPresent()) {
            throw new IllegalArgumentException("only an available session may own an active run");
        }
        var runIds = new HashSet<RunId>();
        activeRun.ifPresent(run -> {
            requireOwner(sessionId, run.sessionId(), "active run");
            if (run.status() == RunStatus.TERMINAL) throw new IllegalArgumentException("active run must be unfinished");
            runIds.add(run.id());
        });
        for (Run run : completedRuns) {
            requireOwner(sessionId, run.sessionId(), "completed run");
            if (run.status() != RunStatus.TERMINAL || !runIds.add(run.id())) {
                throw new IllegalArgumentException("completed runs must be unique terminal runs");
            }
        }
        int unfinishedCompactions = 0;
        var compactionIds = new HashSet<CompactionId>();
        for (Compaction compaction : compactions) {
            requireOwner(sessionId, compaction.sessionId(), "compaction");
            if (!compactionIds.add(compaction.id())) throw new IllegalArgumentException("compaction IDs must be unique");
            if (compaction.status() != CompactionStatus.TERMINAL) unfinishedCompactions++;
        }
        if (unfinishedCompactions > 1) throw new IllegalArgumentException("a session may have at most one unfinished compaction");
        if (status != SessionStatus.AVAILABLE && unfinishedCompactions != 0) {
            throw new IllegalArgumentException("only an available session may own an unfinished compaction");
        }
    }

    public CanonicalSessionState transition(
            SessionStatus next, Optional<SessionOutcome> nextOutcome, long expectedRevision) {
        requireExpected(revision, expectedRevision);
        Objects.requireNonNull(next, "next");
        Objects.requireNonNull(nextOutcome, "nextOutcome");
        boolean allowed = status == SessionStatus.AVAILABLE && next == SessionStatus.TRASHED
                || status == SessionStatus.TRASHED && (next == SessionStatus.AVAILABLE || next == SessionStatus.TOMBSTONED);
        if (!allowed) throw new IllegalStateException("illegal session transition: " + status + " -> " + next);
        if (activeRun.isPresent() || compactions.stream().anyMatch(compaction -> compaction.status() != CompactionStatus.TERMINAL)) {
            throw new IllegalStateException("session with unfinished operation cannot change storage lifecycle");
        }
        return new CanonicalSessionState(
                sessionId, next, nextOutcome, increment(revision), activeRun, completedRuns, compactions);
    }

    public record SessionId(String value) { public SessionId { requireId(value, "sessionId"); } }
    public record RunId(String value) { public RunId { requireId(value, "runId"); } }
    public record TurnId(String value) { public TurnId { requireId(value, "turnId"); } }
    public record AttemptId(String value) { public AttemptId { requireId(value, "attemptId"); } }
    public record ToolExecutionId(String value) { public ToolExecutionId { requireId(value, "toolExecutionId"); } }
    public record PermissionId(String value) { public PermissionId { requireId(value, "permissionId"); } }
    public record CompactionId(String value) { public CompactionId { requireId(value, "compactionId"); } }

    public record Run(
            RunId id,
            SessionId sessionId,
            RunStatus status,
            Optional<RunOutcome> outcome,
            Optional<RunPauseReason> pauseReason,
            long revision,
            List<Turn> turns,
            Instant startedAt,
            Optional<Instant> endedAt) {
        public Run {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(sessionId, "sessionId");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            Objects.requireNonNull(pauseReason, "pauseReason");
            requireRevision(revision);
            turns = List.copyOf(turns);
            Objects.requireNonNull(startedAt, "startedAt");
            Objects.requireNonNull(endedAt, "endedAt");
            requireTerminal(status == RunStatus.TERMINAL, outcome, endedAt, "run");
            if ((status == RunStatus.PAUSED) != pauseReason.isPresent()) throw new IllegalArgumentException("only paused run has pause reason");
            int unfinished = 0;
            for (int index = 0; index < turns.size(); index++) {
                Turn turn = turns.get(index);
                if (!turn.runId().equals(id) || turn.number() != index + 1) throw new IllegalArgumentException("turn ownership and order must match run");
                if (turn.tools().stream().anyMatch(tool -> !tool.sessionId().equals(sessionId))) {
                    throw new IllegalArgumentException("tool belongs to a different session than its run");
                }
                if (turn.status() != TurnStatus.TERMINAL) {
                    unfinished++;
                    if (index != turns.size() - 1) throw new IllegalArgumentException("only final turn may be unfinished");
                }
            }
            if (unfinished > 1 || status == RunStatus.TERMINAL && unfinished != 0) throw new IllegalArgumentException("run and turn lifecycles conflict");
            if (status == RunStatus.PAUSED && (unfinished != 1 || turns.getLast().status() != TurnStatus.PAUSED)) throw new IllegalArgumentException("paused run requires paused current turn");
            if (status == RunStatus.RUNNING && unfinished == 1 && turns.getLast().status() == TurnStatus.PAUSED) throw new IllegalArgumentException("running run cannot own paused current turn");
        }

        public Run transition(RunStatus next, Optional<RunOutcome> nextOutcome,
                              Optional<RunPauseReason> nextPauseReason, Optional<Instant> nextEndedAt,
                              long expectedRevision) {
            requireExpected(revision, expectedRevision);
            Objects.requireNonNull(next, "next");
            boolean allowed = status == RunStatus.RUNNING && (next == RunStatus.CANCELLING || next == RunStatus.PAUSED || next == RunStatus.TERMINAL)
                    || status == RunStatus.CANCELLING && (next == RunStatus.PAUSED || next == RunStatus.TERMINAL)
                    || status == RunStatus.PAUSED && (next == RunStatus.RUNNING || next == RunStatus.TERMINAL);
            if (!allowed) throw new IllegalStateException("illegal run transition: " + status + " -> " + next);
            if (status == RunStatus.PAUSED && pauseReason.orElse(null) == RunPauseReason.CANCELLATION_PENDING && next == RunStatus.RUNNING) {
                throw new IllegalStateException("cancellation-pending run cannot resume");
            }
            return new Run(id, sessionId, next, nextOutcome, nextPauseReason, increment(revision), turns, startedAt, nextEndedAt);
        }
    }

    public record Turn(
            TurnId id,
            RunId runId,
            int number,
            TurnStatus status,
            Optional<TurnOutcome> outcome,
            Optional<TurnPhase> pausedFrom,
            long revision,
            List<Attempt> attempts,
            List<ToolExecution> tools,
            List<Permission> permissions) {
        public Turn {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(runId, "runId");
            if (number < 1) throw new IllegalArgumentException("turn number must be positive");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            Objects.requireNonNull(pausedFrom, "pausedFrom");
            requireRevision(revision);
            attempts = List.copyOf(attempts);
            tools = List.copyOf(tools);
            permissions = List.copyOf(permissions);
            requireTerminal(status == TurnStatus.TERMINAL, outcome, "turn");
            if ((status == TurnStatus.PAUSED) != pausedFrom.isPresent()) throw new IllegalArgumentException("only paused turn records prior phase");
            validateAttempts(attempts, id.value(), true);
            if (status == TurnStatus.MODEL_STREAMING && (attempts.isEmpty() || attempts.getLast().status() != AttemptStatus.RUNNING)) {
                throw new IllegalArgumentException("model-streaming turn requires running current attempt");
            }
            if (status == TurnStatus.WAITING_FOR_TOOLS
                    && (attempts.isEmpty() || attempts.stream().anyMatch(attempt -> attempt.status() != AttemptStatus.TERMINAL))) {
                throw new IllegalArgumentException("tool-waiting turn requires terminal model attempts");
            }
            if (status == TurnStatus.PAUSED && attempts.stream().anyMatch(attempt -> attempt.status() == AttemptStatus.RUNNING)) {
                throw new IllegalArgumentException("paused turn cannot own running attempt");
            }
            if (status == TurnStatus.PAUSED && pausedFrom.orElseThrow() == TurnPhase.MODEL_STREAMING
                    && (attempts.isEmpty() || attempts.getLast().status() != AttemptStatus.PAUSED)) {
                throw new IllegalArgumentException("model-paused turn requires paused current attempt");
            }
            if (status == TurnStatus.TERMINAL && attempts.stream().anyMatch(attempt -> attempt.status() != AttemptStatus.TERMINAL)) {
                throw new IllegalArgumentException("terminal turn requires terminal attempts");
            }
            var toolIds = new HashSet<ToolExecutionId>();
            for (ToolExecution tool : tools) {
                if (!tool.turnId().equals(id) || !tool.runId().equals(runId) || !toolIds.add(tool.id())) throw new IllegalArgumentException("tool ownership must match turn");
                if (status == TurnStatus.MODEL_STREAMING && tool.status() != ToolStatus.TERMINAL) throw new IllegalArgumentException("model-streaming turn requires terminal prior tools");
                if (status == TurnStatus.WAITING_FOR_TOOLS && tool.status() == ToolStatus.PAUSED) throw new IllegalArgumentException("active tool-waiting turn cannot own paused tool");
                if (status == TurnStatus.PAUSED && tool.status() == ToolStatus.RUNNING) throw new IllegalArgumentException("paused turn cannot own running tool");
                if (status == TurnStatus.PAUSED && tool.attempts().stream().anyMatch(attempt -> attempt.status() == AttemptStatus.RUNNING)) throw new IllegalArgumentException("paused turn cannot own running tool attempt");
                if (status == TurnStatus.TERMINAL && tool.status() != ToolStatus.TERMINAL) throw new IllegalArgumentException("terminal turn requires terminal tools");
            }
            var permissionIds = new HashSet<PermissionId>();
            for (Permission permission : permissions) {
                if (!permissionIds.add(permission.id()) || !toolIds.contains(permission.toolExecutionId())) throw new IllegalArgumentException("permission must reference a tool in the same turn");
                ToolExecution tool = tools.stream().filter(candidate -> candidate.id().equals(permission.toolExecutionId())).findFirst().orElseThrow();
                if (!permission.sessionId().equals(tool.sessionId())) throw new IllegalArgumentException("permission and tool must belong to the same session");
                if (permission.status() == PermissionStatus.PENDING
                        && tool.status() != ToolStatus.PREPARED && tool.status() != ToolStatus.PAUSED) {
                    throw new IllegalArgumentException("pending permission requires prepared or paused tool");
                }
                if (status == TurnStatus.TERMINAL && permission.status() != PermissionStatus.RESOLVED) throw new IllegalArgumentException("terminal turn requires resolved permissions");
            }
        }

        public Turn transition(
                TurnStatus next,
                Optional<TurnOutcome> nextOutcome,
                Optional<TurnPhase> nextPausedFrom,
                List<Attempt> nextAttempts,
                List<ToolExecution> nextTools,
                List<Permission> nextPermissions,
                long expectedRevision) {
            requireExpected(revision, expectedRevision);
            Objects.requireNonNull(next, "next");
            boolean allowed = status == TurnStatus.MODEL_STREAMING
                    && (next == TurnStatus.WAITING_FOR_TOOLS || next == TurnStatus.PAUSED || next == TurnStatus.TERMINAL)
                    || status == TurnStatus.WAITING_FOR_TOOLS
                    && (next == TurnStatus.PAUSED || next == TurnStatus.TERMINAL)
                    || status == TurnStatus.PAUSED
                    && (next == TurnStatus.MODEL_STREAMING || next == TurnStatus.WAITING_FOR_TOOLS || next == TurnStatus.TERMINAL);
            if (!allowed) throw new IllegalStateException("illegal turn transition: " + status + " -> " + next);
            return new Turn(id, runId, number, next, nextOutcome, nextPausedFrom,
                    increment(revision), nextAttempts, nextTools, nextPermissions);
        }
    }

    public record Attempt(
            AttemptId id,
            String operationId,
            int number,
            AttemptStep step,
            AttemptStatus status,
            Optional<AttemptOutcome> outcome,
            long revision,
            String resultEntryId) {
        public Attempt {
            Objects.requireNonNull(id, "id");
            requireId(operationId, "operationId");
            if (number < 1) throw new IllegalArgumentException("attempt number must be positive");
            Objects.requireNonNull(step, "step");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireRevision(revision);
            requireId(resultEntryId, "resultEntryId");
            requireTerminal(status == AttemptStatus.TERMINAL, outcome, "attempt");
        }

        public Attempt pause(long expectedRevision) {
            requireExpected(revision, expectedRevision);
            if (status != AttemptStatus.RUNNING) throw new IllegalStateException("only running attempt may pause");
            return new Attempt(id, operationId, number, step, AttemptStatus.PAUSED, Optional.empty(), increment(revision), resultEntryId);
        }

        public Attempt finish(AttemptOutcome terminalOutcome, long expectedRevision) {
            requireExpected(revision, expectedRevision);
            Objects.requireNonNull(terminalOutcome, "terminalOutcome");
            boolean allowed = status == AttemptStatus.RUNNING && terminalOutcome != AttemptOutcome.SUPERSEDED
                    || status == AttemptStatus.PAUSED && terminalOutcome == AttemptOutcome.SUPERSEDED;
            if (!allowed) throw new IllegalStateException("attempt outcome is illegal from " + status + ": " + terminalOutcome);
            return new Attempt(id, operationId, number, step, AttemptStatus.TERMINAL,
                    Optional.of(terminalOutcome), increment(revision), resultEntryId);
        }

        public Attempt supersede(long expectedRevision) {
            return finish(AttemptOutcome.SUPERSEDED, expectedRevision);
        }
    }

    public record ToolExecution(
            ToolExecutionId id,
            SessionId sessionId,
            RunId runId,
            TurnId turnId,
            String toolCallId,
            String toolName,
            String resultEntryId,
            List<Attempt> attempts,
            ToolRetryContract retryContract,
            Optional<String> resumeToken,
            ToolStatus status,
            Optional<ToolOutcome> outcome,
            long revision) {
        public ToolExecution {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(sessionId, "sessionId");
            Objects.requireNonNull(runId, "runId");
            Objects.requireNonNull(turnId, "turnId");
            requireId(toolCallId, "toolCallId");
            requireId(toolName, "toolName");
            requireId(resultEntryId, "resultEntryId");
            attempts = List.copyOf(attempts);
            if (attempts.isEmpty()) throw new IllegalArgumentException("tool must have an attempt");
            validateAttempts(attempts, id.value(), false);
            retryContract = retryContract == null ? ToolRetryContract.NON_RETRYABLE : retryContract;
            Objects.requireNonNull(resumeToken, "resumeToken");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireRevision(revision);
            requireTerminal(status == ToolStatus.TERMINAL, outcome, "tool");
            Attempt attempt = attempts.getLast();
            if (attempts.stream().anyMatch(candidate -> candidate.step() != AttemptStep.TOOL
                    || !candidate.resultEntryId().equals(resultEntryId))) {
                throw new IllegalArgumentException("tool attempt identity must match tool");
            }
            if (status == ToolStatus.RUNNING && attempt.status() != AttemptStatus.RUNNING
                    || status == ToolStatus.PAUSED && attempt.status() != AttemptStatus.PAUSED
                    || status == ToolStatus.TERMINAL && attempt.status() != AttemptStatus.TERMINAL) {
                throw new IllegalArgumentException("tool and attempt lifecycles conflict");
            }
        }

        public ToolExecution transition(ToolStatus next, Optional<ToolOutcome> nextOutcome,
                                        List<Attempt> nextAttempts, long expectedRevision) {
            requireExpected(revision, expectedRevision);
            Objects.requireNonNull(next, "next");
            boolean allowed = status == ToolStatus.PREPARED
                    && (next == ToolStatus.RUNNING || next == ToolStatus.PAUSED || next == ToolStatus.TERMINAL)
                    || status == ToolStatus.RUNNING && (next == ToolStatus.PAUSED || next == ToolStatus.TERMINAL)
                    || status == ToolStatus.PAUSED
                    && (next == ToolStatus.PREPARED || next == ToolStatus.RUNNING || next == ToolStatus.TERMINAL);
            if (!allowed) throw new IllegalStateException("illegal tool transition: " + status + " -> " + next);
            if (status == ToolStatus.PAUSED
                    && (next == ToolStatus.PREPARED || next == ToolStatus.RUNNING) && !mayResume()) {
                throw new IllegalStateException("tool retry contract forbids recovery");
            }
            return new ToolExecution(id, sessionId, runId, turnId, toolCallId, toolName, resultEntryId,
                    nextAttempts, retryContract, resumeToken, next, nextOutcome, increment(revision));
        }

        public boolean mayResume() {
            return retryContract == ToolRetryContract.READ_ONLY || retryContract == ToolRetryContract.IDEMPOTENT
                    || retryContract == ToolRetryContract.RESUMABLE && resumeToken.isPresent();
        }
    }

    public record Permission(
            PermissionId id,
            SessionId sessionId,
            ToolExecutionId toolExecutionId,
            PermissionStatus status,
            Optional<PermissionOutcome> outcome,
            long revision,
            Instant expiresAt) {
        public Permission {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(sessionId, "sessionId");
            Objects.requireNonNull(toolExecutionId, "toolExecutionId");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireRevision(revision);
            Objects.requireNonNull(expiresAt, "expiresAt");
            requireTerminal(status == PermissionStatus.RESOLVED, outcome, "permission");
        }

        public Permission resolve(PermissionOutcome decision, long expectedRevision, Instant now) {
            requireExpected(revision, expectedRevision);
            if (status != PermissionStatus.PENDING) throw new IllegalStateException("permission already resolved");
            PermissionOutcome resolved = now.isBefore(expiresAt) ? Objects.requireNonNull(decision, "decision") : PermissionOutcome.EXPIRED;
            return new Permission(id, sessionId, toolExecutionId, PermissionStatus.RESOLVED,
                    Optional.of(resolved), increment(revision), expiresAt);
        }
    }

    public record Compaction(
            CompactionId id,
            SessionId sessionId,
            CompactionStatus status,
            Optional<CompactionOutcome> outcome,
            long revision,
            List<Attempt> attempts,
            Optional<String> resultEntryId) {
        public Compaction {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(sessionId, "sessionId");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireRevision(revision);
            attempts = List.copyOf(attempts);
            if (attempts.isEmpty()) throw new IllegalArgumentException("compaction must have an attempt");
            validateAttempts(attempts, id.value(), true);
            Objects.requireNonNull(resultEntryId, "resultEntryId");
            requireTerminal(status == CompactionStatus.TERMINAL, outcome, "compaction");
            Attempt attempt = attempts.getLast();
            if (attempt.step() != AttemptStep.COMPACTION) throw new IllegalArgumentException("compaction attempt identity must match compaction");
            if (status == CompactionStatus.RUNNING && attempt.status() != AttemptStatus.RUNNING
                    || status == CompactionStatus.PAUSED && attempt.status() != AttemptStatus.PAUSED
                    || status == CompactionStatus.TERMINAL && attempt.status() != AttemptStatus.TERMINAL) {
                throw new IllegalArgumentException("compaction and attempt lifecycles conflict");
            }
            if ((outcome.orElse(null) == CompactionOutcome.COMPLETED) != resultEntryId.isPresent()) {
                throw new IllegalArgumentException("only completed compaction has result entry");
            }
        }

        public Compaction transition(CompactionStatus next, Optional<CompactionOutcome> nextOutcome,
                                     List<Attempt> nextAttempts, Optional<String> nextResultEntryId,
                                     long expectedRevision) {
            requireExpected(revision, expectedRevision);
            Objects.requireNonNull(next, "next");
            boolean allowed = status == CompactionStatus.RUNNING
                    && (next == CompactionStatus.PAUSED || next == CompactionStatus.TERMINAL)
                    || status == CompactionStatus.PAUSED
                    && (next == CompactionStatus.RUNNING || next == CompactionStatus.TERMINAL);
            if (!allowed) throw new IllegalStateException("illegal compaction transition: " + status + " -> " + next);
            return new Compaction(id, sessionId, next, nextOutcome, increment(revision),
                    nextAttempts, nextResultEntryId);
        }
    }

    public enum SessionStatus { AVAILABLE, TRASHED, TOMBSTONED }
    public enum SessionOutcome { DELETED }
    public enum RunStatus { RUNNING, CANCELLING, PAUSED, TERMINAL }
    public enum RunOutcome { COMPLETED, ABORTED, FAILED, DECLINED }
    public enum RunPauseReason { USER_REQUESTED, HOST_RESTART, CANCELLATION_PENDING }
    public enum TurnStatus { MODEL_STREAMING, WAITING_FOR_TOOLS, PAUSED, TERMINAL }
    public enum TurnOutcome { COMPLETED, ABORTED, FAILED }
    public enum TurnPhase { MODEL_STREAMING, WAITING_FOR_TOOLS }
    public enum AttemptStatus { RUNNING, PAUSED, TERMINAL }
    public enum AttemptOutcome { SUCCEEDED, FAILED, INTERRUPTED, SUPERSEDED }
    public enum AttemptStep { ASSISTANT, BRANCH_SUMMARY, TOOL, COMPACTION }
    public enum ToolStatus { PREPARED, RUNNING, PAUSED, TERMINAL }
    public enum ToolOutcome { SUCCEEDED, DENIED, CANCELLED, FAILED, INTERRUPTED }
    public enum ToolRetryContract { READ_ONLY, IDEMPOTENT, RESUMABLE, NON_RETRYABLE }
    public enum PermissionStatus { PENDING, RESOLVED }
    public enum PermissionOutcome { ALLOWED, DENIED, EXPIRED }
    public enum CompactionStatus { RUNNING, PAUSED, TERMINAL }
    public enum CompactionOutcome { COMPLETED, CANCELLED, FAILED }

    private static void validateAttempts(List<Attempt> attempts, String operationId, boolean uniqueResultEntries) {
        var ids = new HashSet<AttemptId>();
        var results = new HashSet<String>();
        int unfinished = 0;
        for (int index = 0; index < attempts.size(); index++) {
            Attempt attempt = attempts.get(index);
            if (attempt.number() != index + 1 || !attempt.operationId().equals(operationId)) throw new IllegalArgumentException("attempt order and owner must match operation");
            if (!ids.add(attempt.id()) || uniqueResultEntries && !results.add(attempt.resultEntryId())) throw new IllegalArgumentException("attempt identities must be unique");
            if (attempt.status() != AttemptStatus.TERMINAL) {
                unfinished++;
                if (index != attempts.size() - 1) throw new IllegalArgumentException("only final attempt may be unfinished");
            }
        }
        if (unfinished > 1) throw new IllegalArgumentException("operation may have at most one unfinished attempt");
    }

    private static void requireTerminal(boolean terminal, Optional<?> outcome, String name) {
        if (terminal != outcome.isPresent()) throw new IllegalArgumentException(name + " outcome is present exactly in terminal status");
    }
    private static void requireTerminal(boolean terminal, Optional<?> outcome, Optional<Instant> endedAt, String name) {
        requireTerminal(terminal, outcome, name);
        if (terminal != endedAt.isPresent()) throw new IllegalArgumentException(name + " end time is present exactly in terminal status");
    }
    private static void requireOwner(Object expected, Object actual, String name) {
        if (!expected.equals(actual)) throw new IllegalArgumentException(name + " belongs to a different parent");
    }
    private static void requireId(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
    private static void requireRevision(long revision) {
        if (revision < 0) throw new IllegalArgumentException("revision must be non-negative");
    }
    private static void requireExpected(long actual, long expected) {
        requireRevision(expected);
        if (actual != expected) throw new IllegalStateException("revision conflict: expected " + expected + ", current " + actual);
    }
    private static long increment(long revision) {
        try { return Math.incrementExact(revision); }
        catch (ArithmeticException exception) { throw new IllegalStateException("revision exhausted", exception); }
    }
}

